/* C API of the Rust port of `src/facade.c`, generated by carcinize. */
#ifndef FACADE_RS_H
#define FACADE_RS_H

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include <sys/types.h>

long parse_long(const char *text, int base);
int parse_int(const char *text);
double parse_double(const char *text);
size_t span(const char *text, const char *accept);
int compare(const char *a, const char *b);
int is_alpha(int c);
int is_space(int c);
int is_punct(int c);
int to_upper(int c);

/* The same functions under `carcinize_` names, for shadow runs. */
long carcinize_parse_long(const char *text, int base);
int carcinize_parse_int(const char *text);
double carcinize_parse_double(const char *text);
size_t carcinize_span(const char *text, const char *accept);
int carcinize_compare(const char *a, const char *b);
int carcinize_is_alpha(int c);
int carcinize_is_space(int c);
int carcinize_is_punct(int c);
int carcinize_to_upper(int c);

#endif /* FACADE_RS_H */
